/**
 * Reserve project slug on the Veryfront API
 *
 * Handles slug conflicts by appending random suffixes
 *
 * @module cli/shared/reserve-slug
 */
import { getEnvironmentConfig } from "../../src/config/index.js";
import { capitalizeSeparatedWords } from "../../src/utils/case-utils.js";
import { randomSuffix } from "./slug.js";
import { getApiUrl } from "./constants.js";
import { ApiErrorSchema, formatApiError } from "./config.js";
function slugToName(slug) {
    return capitalizeSeparatedWords(slug, "-", " ");
}
export class ProjectSlugConflictError extends Error {
    slug;
    constructor(slug) {
        super(`Project slug "${slug}" is already in use.`);
        this.slug = slug;
        this.name = "ProjectSlugConflictError";
    }
}
const MAX_SLUG_ATTEMPTS = 10;
export async function reserveProjectSlug(slug, token, env = getEnvironmentConfig(), apiUrl = getApiUrl(env), options = {}) {
    const name = slugToName(slug);
    let currentSlug = slug;
    for (let attempt = 1; attempt <= MAX_SLUG_ATTEMPTS; attempt++) {
        const result = await tryCreateProject(currentSlug, name, token, apiUrl, options.transport);
        if (result.success) {
            return {
                slug: currentSlug,
                projectId: result.projectId ?? "",
                created: true,
            };
        }
        if (!result.isSlugTaken) {
            throw new Error(result.error ?? "Failed to create project");
        }
        if (options.allowAlternativeSlug === false) {
            throw new ProjectSlugConflictError(slug);
        }
        currentSlug = `${slug}-${randomSuffix()}`;
    }
    throw new Error(`Could not find available slug after ${MAX_SLUG_ATTEMPTS} attempts`);
}
async function tryCreateProject(slug, name, token, apiUrl, transport = fetch) {
    try {
        const response = await transport(`${apiUrl.replace(/(?<!\/)\/+$/, "")}/projects`, {
            method: "POST",
            headers: {
                Authorization: `Bearer ${token}`,
                "Content-Type": "application/json",
                Accept: "application/json",
            },
            body: JSON.stringify({ slug, name }),
        });
        if (response.ok) {
            const data = (await response.json());
            return { success: true, projectId: data.id };
        }
        if (response.status === 409) {
            return { success: false, isSlugTaken: true };
        }
        const fallback = `HTTP ${response.status}`;
        const parsed = ApiErrorSchema.safeParse(await response.json().catch(() => ({})));
        return {
            success: false,
            error: parsed.success ? formatApiError(parsed.data, fallback) : fallback,
        };
    }
    catch (error) {
        return { success: false, error: error instanceof Error ? error.message : String(error) };
    }
}
export async function isSlugAvailable(slug, token, env = getEnvironmentConfig()) {
    try {
        const response = await fetch(`${getApiUrl(env)}/projects/${slug}`, {
            method: "HEAD",
            headers: { Authorization: `Bearer ${token}` },
        });
        return response.status === 404;
    }
    catch {
        return true;
    }
}
